  `estado` enum('iniciado','finalizado','error') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'iniciado',
  `procesados` int NOT NULL DEFAULT '0',
  `cargados` int NOT NULL DEFAULT '0',
  `errores` int NOT NULL DEFAULT '0',
  `mensaje` text COLLATE utf8mb4_unicode_ci,
  `started_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `finished_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_stock_script_runs_importacion` (`importacion_id`),
  CONSTRAINT `fk_stock_script_runs_importacion` FOREIGN KEY (`importacion_id`) REFERENCES `stock_importaciones` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
