--
-- Table structure for table `stock_valores_carga`
--

DROP TABLE IF EXISTS `stock_valores_carga`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `stock_valores_carga` (
  `id` int NOT NULL AUTO_INCREMENT,
  `item_id` int NOT NULL,
  `codigo_articulo` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `stock_minimo_nuevo` int DEFAULT NULL,
  `stock_maximo_nuevo` int DEFAULT NULL,
  `estado` enum('pendiente','listo','en_proceso','cargado','error') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pendiente',
  `tipo_operacion` enum('carga_inicial','actualizacion') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'carga_inicial',
  `mensaje_error` text COLLATE utf8mb4_unicode_ci,
  `actualizado_por` int DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `item_id` (`item_id`),
  KEY `idx_stock_valores_estado` (`estado`),
  KEY `idx_stock_valores_codigo` (`codigo_articulo`),
  KEY `fk_stock_valores_usuario` (`actualizado_por`),
  CONSTRAINT `fk_stock_valores_item` FOREIGN KEY (`item_id`) REFERENCES `stock_items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_stock_valores_usuario` FOREIGN KEY (`actualizado_por`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=460 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

