--
-- Table structure for table `trimestre_importaciones`
--

DROP TABLE IF EXISTS `trimestre_importaciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `trimestre_importaciones` (
  `id` int NOT NULL AUTO_INCREMENT,
  `archivo_nombre` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `archivo_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `hospital` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sector` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `periodo_desde` date DEFAULT NULL,
  `periodo_hasta` date DEFAULT NULL,
  `anio` int DEFAULT NULL,
  `trimestre` tinyint DEFAULT NULL,
  `total_items` int NOT NULL DEFAULT '0',
  `creado_por` int DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_trimestre_hash` (`archivo_hash`),
  UNIQUE KEY `uq_trimestre_periodo` (`sector`,`anio`,`trimestre`),
  KEY `idx_trimestre_anio` (`anio`,`trimestre`),
  KEY `fk_trimestre_importaciones_usuario` (`creado_por`),
  CONSTRAINT `fk_trimestre_importaciones_usuario` FOREIGN KEY (`creado_por`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

