--
-- Table structure for table `trimestre_items`
--

DROP TABLE IF EXISTS `trimestre_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `trimestre_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `trimestre_importacion_id` int NOT NULL,
  `codigo_articulo` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre_generico` text COLLATE utf8mb4_unicode_ci,
  `concentracion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `forma` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `presentacion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cantidad` decimal(12,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_trimestre_item` (`trimestre_importacion_id`,`codigo_articulo`),
  KEY `idx_trimestre_items_codigo` (`codigo_articulo`),
  CONSTRAINT `fk_trimestre_items_importacion` FOREIGN KEY (`trimestre_importacion_id`) REFERENCES `trimestre_importaciones` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3039 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

